head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > footerCaptionAuto]<br/>GridView 컴포넌트의 Footer Table 에 caption 요소를 자동 생성할지 설정합니다.",
    "validation" : [
        "GridView 컴포넌트의 Footer Table 에 caption 요소를 자동 생성할지 설정합니다. captionTitle 속성이 설정되지 않으면 footerCaptionAuto 는 항상 false 로 동작하며, footerCaption 속성이 설정된 경우 footerCaptionAuto 는 항상 false 로 동작합니다.",
        "true 로 설정하면 Footer Table 에 '{captionTitle}합계를 나타낸 표' 값으로 caption 요소가 생성됩니다.",
        "false (default) 로 설정하면 Footer Table 에 caption 요소를 자동으로 생성하지 않습니다.",
        "setCaptionAuto() 메소드 실행 시 Footer Table 의 caption 요소값은 재생성하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_footerCaptionAuto : 미설정('') / true / false. 이번 샘플의 주 대상 (Property 미설정 케이스 포함)
    //  - con_captionTitle      : 문자열. 빈 값이면 captionTitle 속성을 부여하지 않음 (미설정 시 footerCaptionAuto 는 항상 false 동작)
    //  - con_footerCaption     : 문자열. 빈 값이면 footerCaption 속성을 부여하지 않음 (설정 시 footerCaptionAuto 무시)
    let footerCaptionAutoVal = con_footerCaptionAuto.getText();
    let captionTitleVal      = con_captionTitle.getValue();
    let footerCaptionVal     = con_footerCaption.getValue();

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Property 설정은 createCList 공통 함수 사용 (빈 문자열 value 는 자동 제외 → 미설정 처리)
    let properties = {
        footerCaptionAuto: footerCaptionAutoVal,
        captionTitle: captionTitleVal,
        footerCaption: footerCaptionVal,
        dataList: "data:dlt_bind",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFooterCaptionAuto = (footerCaptionAutoVal === '') ? '미설정' : footerCaptionAutoVal;
    let lblCaptionTitle      = (captionTitleVal      === '') ? '미설정' : captionTitleVal;
    let lblFooterCaption     = (footerCaptionVal     === '') ? '미설정' : footerCaptionVal;
    $c.gcm.createLabel('label="footerCaptionAuto=' + lblFooterCaptionAuto + ' / captionTitle=' + lblCaptionTitle + ' / footerCaption=' + lblFooterCaption + ' 로 GridView 생성 (Header 4컬럼 + gBody + Footer 1행)"', '', 'label1');

    // target 생성 (footerCaptionAuto / captionTitle / footerCaption 조건부, Footer Table 포함)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="footerCaptionAuto 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Footer Table 의 caption 요소 텍스트를 DOM 으로 읽어 반환 (없으면 null)
scwin.getFooterCaptionText = function () {
    let footTable = document.querySelector("table[id*='target1_foot_table']");
    if (!footTable) {
        return null;
    }
    let caption = footTable.getElementsByTagName("caption")[0];
    return caption ? caption.textContent : null;
}



// 현재 Footer Table caption 요소(렌더) / 속성값 확인 (@description / @propval)
scwin.btn_checkFooterCaption_onclick = function () {
    let captionText = scwin.getFooterCaptionText();
    wf_body_bottom.getObj("scwin").setReturnValue("렌더 caption 요소 : " + (captionText === null ? '미생성(caption 요소 없음)' : "'" + captionText + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("footerCaptionAuto 속성값 : " + target1.options.footerCaptionAuto);
    wf_body_bottom.getObj("scwin").setReturnValue("captionTitle 속성값 : '" + target1.options.captionTitle + "' / footerCaption 속성값 : '" + target1.options.footerCaption + "'");
}



// setCaptionAuto 호출 전/후 Footer Table caption 요소값이 재생성되지 않음을 확인 (@spec)
scwin.btn_setCaptionAuto_onclick = function () {
    let val = par_setCaptionAuto.getValue();

    // 호출 전 footer caption (렌더) 값
    let beforeCaption = scwin.getFooterCaptionText();
    wf_body_bottom.getObj("scwin").setReturnValue("[setCaptionAuto 호출 전 footer caption] " + (beforeCaption === null ? '미생성' : "'" + beforeCaption + "'"));

    // setCaptionAuto 실행 (인자 미입력 시 생략 호출)
    if (val === '') {
        target1.setCaptionAuto();
    } else {
        target1.setCaptionAuto(val);
    }

    // 호출 후 footer caption (렌더) 값 -> @spec: Footer Table caption 요소값은 재생성하지 않음
    let afterCaption = scwin.getFooterCaptionText();
    wf_body_bottom.getObj("scwin").setReturnValue("[setCaptionAuto('" + val + "') 호출 후 footer caption] " + (afterCaption === null ? '미생성' : "'" + afterCaption + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("[footer caption 재생성 안 됨(호출 전후 동일)] " + (beforeCaption === afterCaption));
}
